create schema if not exists cron;
create table if not exists cron.job (jobid bigserial primary key, schedule text, command text, nodename text default 'localhost', nodeport int default 5432, database text default current_database(), username text default current_user, active boolean default true, jobname text unique);
create table if not exists cron.job_run_details (jobid bigint, runid bigserial, job_pid int, database text, username text, command text, status text, return_message text, start_time timestamptz, end_time timestamptz);
create or replace function cron.schedule(job_name text, schedule text, command text) returns bigint language plpgsql as $$ declare v bigint; begin insert into cron.job(jobname,schedule,command) values (job_name,schedule,command) on conflict (jobname) do update set schedule=excluded.schedule, command=excluded.command returning jobid into v; return v; end $$;
create or replace function cron.schedule(schedule text, command text) returns bigint language sql as $$ insert into cron.job(schedule,command) values (schedule,command) returning jobid $$;
create or replace function cron.unschedule(job_name text) returns boolean language plpgsql as $$ begin delete from cron.job where jobname = job_name; return true; end $$;
create or replace function cron.unschedule(job_id bigint) returns boolean language plpgsql as $$ begin delete from cron.job where jobid = job_id; return true; end $$;
